WITH filtered AS (SELECT *, ROUND(sqft * 100, 2) AS adjusted_sqft, COALESCE(region, 'OTHER') AS region_clean FROM stores WHERE region IS NOT NULL AND LENGTH(store_name) < 12) SELECT CASE WHEN adjusted_sqft >= 65 THEN 'LARGE' ELSE 'SMALL' END AS adjusted_sqft_tier, region, COUNT_IF(city = 'Berlin') AS berlin_events, STDDEV_SAMP(sqft) AS sqft_stddev, COUNT(DISTINCT id) AS distinct_ids, GROUPING_ID() AS grouping_level FROM filtered GROUP BY GROUPING SETS ((CASE WHEN adjusted_sqft >= 65 THEN 'LARGE' ELSE 'SMALL' END, region), (CASE WHEN adjusted_sqft >= 65 THEN 'LARGE' ELSE 'SMALL' END)) HAVING sqft_stddev > 0 ORDER BY adjusted_sqft_tier DESC NULLS LAST;
